{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:rgba(255,255,255,0.06);--glass:rgba(255,255,255,0.04);--muted:rgba(255,255,255,0.6);--accent:#8bd3c7}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6f7f3;background:linear-gradient(180deg,var(--bg),#071018);-webkit-font-smoothing:antialiased}
    .app{min-height:100vh;display:flex;flex-direction:column;background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;backdrop-filter:blur(8px);background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#3fb0c9);box-shadow:0 6px 18px rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;color:#062022;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-size:15px}
    .cta{background:var(--accent);color:#042; padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}
    main{flex:1;display:grid;grid-template-columns:1fr 420px;gap:28px;padding:40px 28px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:14px;padding:24px;box-shadow:0 6px 30px rgba(2,6,23,0.6)}
    h1{margin:0 0 6px 0;font-size:28px;color:#e9fff9}
    p.lead{margin:0 0 16px 0;color:var(--muted);line-height:1.5}
    .meta{display:flex;gap:12px;color:var(--muted);font-size:14px}
    .badge{background:var(--glass);padding:8px 10px;border-radius:10px}
    .hero-quote{font-style:italic;color:#cff6ef;margin-top:14px}
    .proof{margin-top:18px}
    .testimonial{min-height:88px;display:flex;flex-direction:column;justify-content:center}
    .t-text{color:#dffbf6;font-size:15px}
    .t-author{color:var(--muted);font-size:13px;margin-top:10px}
    .badges{display:flex;gap:10px;margin-top:12px}
    .cred{background:rgba(255,255,255,0.03);padding:8px;border-radius:8px;position:relative}
    .cred:hover .tip{opacity:1;transform:translateY(0)}
    .tip{position:absolute;left:50%;transform:translate(-50%,6px);bottom:110%;white-space:nowrap;background:#062022;color:#bff3ea;padding:6px 8px;border-radius:6px;font-size:12px;opacity:0;transition:all 180ms ease}
    .aside h3{margin-top:0}
    .cta-block{display:flex;flex-direction:column;gap:12px}
    .ghost{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:10px;border-radius:10px;text-decoration:none}
    footer{padding:18px 28px;color:var(--muted);font-size:13px}
    @media(max-width:920px){main{grid-template-columns:1fr;padding:24px} .aside{order:2}}
  </style>
</head>
<body>
  <div class="app">
    <header>
      <div class="brand">
        <div class="logo">SB</div>
        <div>
          <div style="font-weight:700;color:#e6fff9">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
        </div>
      </div>
      <nav aria-label="Main navigation">
        <a href="index.html">Gatherings</a>
        <a href="events.html">Calendar</a>
        <a href="private-sessions.html">Private</a>
        <a href="pricing.html">Memberships</a>
        <a href="about.html">Who we are</a>
        <a href="faq.html">Questions</a>
        <a class="cta" href="book.html">Reserve time</a>
      </nav>
    </header>

    <main>
      <section class="panel">
        <h1>About our membership circle</h1>
        <p class="lead">A steady membership that centers practical rest. Members receive priority access to group sound gatherings, a rotating program of tonal sessions, and a modest library of guided recordings. We emphasize clarity, predictable structure, and tangible calm.</p>
        <div class="meta">
          <div class="badge">Memberships • Flexible</div>
          <div class="badge">Sessions weekly</div>
          <div class="badge">{{CITY}}, {{STATE}}</div>
        </div>
        <div class="hero-quote">Sound applied with intention: predictable rhythms, clear transitions, quiet recovery.</div>

        <div class="proof" id="proof-rotator">
          <div class="testimonial" aria-live="polite">
            <div class="t-text" id="t-text">"The sessions helped me get a firmer rest rhythm without leaving weekday routines."</div>
            <div class="t-author" id="t-author">— Mara, member</div>
          </div>
          <div class="badges" id="badges">
            <div class="cred" tabindex="0">
              Trusted Organizer
              <div class="tip">Organizing partners since 2018</div>
            </div>
            <div class="cred" tabindex="0">
              Venue Certified
              <div class="tip">Safety and accessibility audited</div>
            </div>
            <div class="cred" tabindex="0">
              Member-rated 4.8
              <div class="tip">Based on anonymous surveys</div>
            </div>
          </div>
        </div>

        <h3 style="margin-top:22px">Our approach</h3>
        <p class="lead">Sessions are arranged in predictable segments: arrival and settling, tone layers with clear cues, and a guided re-orientation. Each meeting is led by trained facilitators and designed to support daily recovery rather than deep therapy.</p>

        <details style="margin-top:12px;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px">
          <summary style="cursor:pointer;color:var(--muted)">Safety and contraindications</summary>
          <div style="margin-top:8px;color:var(--muted);font-size:14px;line-height:1.5">Not suitable for people with uncontrolled epilepsy, certain types of implanted medical devices without prior medical approval, or unstable cardiovascular conditions. If you are pregnant, have a history of dissociation, or are under psychiatric crisis, consult a medical professional before attending. Our facilitators can adapt sessions; please disclose health concerns when booking.</div>
        </details>
      </section>

      <aside class="panel aside">
        <h3>Membership highlights</h3>
        <p class="lead">Members enjoy discounted booking, early notice of limited gatherings, and curated recordings for home practice. Membership is billed monthly and can be paused.</p>

        <div class="cta-block" style="margin-top:18px">
          <a class="cta" href="pricing.html">View membership tiers</a>
          <a class="ghost" href="contact.html">Talk to us — {{EMAIL}}</a>
        </div>

        <div style="margin-top:18px;color:var(--muted);font-size:13px">Questions by phone? <a href="tel:{{PHONE}}" style="color:#bff3ea;text-decoration:none">{{PHONE}}</a></div>
      </aside>
    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;gap:20px">
        <div>&copy; <strong>{{BUSINESS_NAME}}</strong> — A member-first sound space</div>
        <div style="color:var(--muted)">Contact: <a href="mailto:{{EMAIL}}" style="color:#bff3ea">{{EMAIL}}</a></div>
      </div>
    </footer>
  </div>

  <script>
    (function(){
      // Simple proof rotator
      const testimonials=[
        {t:'"The sessions helped me get a firmer rest rhythm without leaving weekday routines."',a:'Mara, member'},
        {t:'"Reliable structure and gentle tone work — noticeable improvement in sleep clarity."',a:'Jordan, educator'},
        {t:'"I value the short, focused meetings. It fits my week and my attention."',a:'Sanjay, engineer'}
      ];
      const tText=document.getElementById('t-text');
      const tAuthor=document.getElementById('t-author');
      let i=0;
      setInterval(()=>{
        i=(i+1)%testimonials.length;
        tText.textContent = testimonials[i].t;
        tAuthor.textContent = '— '+testimonials[i].a;
      },4200);

      // Simple tooltip accessibility: show tip on focus
      document.querySelectorAll('.cred').forEach(el=>{
        el.addEventListener('focus',()=>{el.querySelector('.tip').style.opacity=1;el.querySelector('.tip').style.transform='translateY(0)'});
        el.addEventListener('blur',()=>{el.querySelector('.tip').style.opacity=0;el.querySelector('.tip').style.transform='translateY(6px)'});
      });
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071018;--card:rgba(255,255,255,0.04);--muted:rgba(255,255,255,0.6);--accent:#93e3d8}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#eafff9;background:linear-gradient(180deg,var(--bg),#051016);min-height:100vh;background-image:url('assets/img/pattern.svg')}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px;background:rgba(255,255,255,0.01)}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#36b4c3);display:flex;align-items:center;justify-content:center;font-weight:700}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{padding:28px;max-width:1100px;margin:0 auto;display:grid;grid-template-columns:1fr 360px;gap:22px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:22px;border-radius:12px}
    h1{margin:0 0 8px 0}
    .faq-list{display:flex;flex-direction:column;gap:12px;margin-top:14px}
    details{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    summary{cursor:pointer;color:var(--muted);font-weight:600}
    .answer{margin-top:8px;color:var(--muted);line-height:1.5}
    .note{font-size:13px;color:#c5fff5;margin-top:10px}
    .gallery{display:flex;flex-direction:column;gap:12px}
    .testimonial{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    .t-text{color:#e8fffb}
    .credits{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .cred{padding:6px 8px;border-radius:8px;background:rgba(255,255,255,0.02);font-size:13px;position:relative}
    .cred .tip{position:absolute;left:50%;transform:translate(-50%,6px);bottom:110%;background:#031616;color:#bff7ec;padding:6px;border-radius:6px;font-size:12px;opacity:0;transition:all 160ms ease}
    .cred:hover .tip{opacity:1;transform:translate(-50%,0)}
    footer{padding:18px 26px;color:var(--muted)}
    @media(max-width:860px){main{grid-template-columns:1fr;padding:18px} .aside{order:2}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Main nav">
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="pricing.html">Memberships</a>
      <a href="about.html">Who we are</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <section class="panel">
      <h1>Frequently asked questions</h1>
      <div class="faq-list">
        <details>
          <summary>What should I expect at a group meeting?</summary>
          <div class="answer">Arrive 10–15 minutes early for a brief orientation, settle into a supported posture, then follow the facilitator's clear cues. Sessions end with a guided return so you leave oriented and steady.</div>
        </details>

        <details>
          <summary>How does membership work?</summary>
          <div class="answer">Membership grants priority booking, a modest discount on private sessions, and access to a recorded library. Billing is monthly; members may pause enrollment with notice.</div>
        </details>

        <details>
          <summary>Can I attend if I'm pregnant or have medical concerns?</summary>
          <div class="answer">If you are pregnant, have a pacemaker, are undergoing active psychiatric care, or have a cardio condition, please consult with your clinician before attending. Share health details confidentially on booking so facilitators can adapt the experience when possible.</div>
        </details>

        <details>
          <summary>Are recordings provided?</summary>
          <div class="answer">Members have access to short, practical recordings focused on settling and breath awareness. They are intended for daily practice, not as medical treatment.</div>
        </details>

        <details>
          <summary>What is your refund or transfer policy?</summary>
          <div class="answer">Tickets can be transferred to another date up to 48 hours before the session. Memberships can be paused or canceled according to the terms displayed on the Memberships page.</div>
        </details>
      </div>

      <div style="margin-top:18px;background:rgba(255,255,255,0.01);padding:12px;border-radius:10px">
        <strong>Contraindications (brief)</strong>
        <div class="note">Sound work is not a substitute for medical care. Avoid attendance during active psychiatric crisis, untreated severe cardiovascular issues, or when medical devices may be affected. When in doubt, seek medical approval and notify us ahead of arrival.</div>
      </div>
    </section>

    <aside class="panel aside">
      <h3>Proof gallery</h3>
      <div class="gallery" id="proof">
        <div class="testimonial" id="test-1"><div class="t-text">"Short, steady sessions that fit my week — I notice better evenings."</div><div style="color:var(--muted);font-size:13px;margin-top:8px">— Len</div></div>
        <div class="testimonial" id="test-2" style="display:none"><div class="t-text">"The facilitators are precise; transitions are clear and calming."</div><div style="color:var(--muted);font-size:13px;margin-top:8px">— Asha</div></div>
        <div class="testimonial" id="test-3" style="display:none"><div class="t-text">"Membership made it easier to keep a consistent rest practice."</div><div style="color:var(--muted);font-size:13px;margin-top:8px">— Tomas</div></div>

        <div class="credits" style="margin-top:8px">
          <div class="cred" tabindex="0">Partner Venues<div class="tip">Local auditoriums and studios</div></div>
          <div class="cred" tabindex="0">Health Reviewed<div class="tip">Reviewed by wellness advisors</div></div>
          <div class="cred" tabindex="0">Member Rated<div class="tip">4.7 average score</div></div>
        </div>

        <div style="margin-top:12px;display:flex;gap:8px">
          <button id="prev" style="flex:1;padding:8px;border-radius:8px;background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted)">Previous</button>
          <button id="next" style="flex:1;padding:8px;border-radius:8px;background:var(--accent);border:none;color:#032020">Next</button>
        </div>
      </div>

      <div style="margin-top:18px;color:var(--muted);font-size:13px">Need direct answers? <a href="contact.html" style="color:#caffef;text-decoration:none">Contact us</a> or call <a href="tel:{{PHONE}}" style="color:#caffef">{{PHONE}}</a></div>
    </aside>
  </main>

  <footer>
    <div style="max-width:1100px;margin:18px auto;color:var(--muted);font-size:13px">Email: <a href="mailto:{{EMAIL}}" style="color:#bff7ec">{{EMAIL}}</a> • City: {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    (function(){
      // Rotate three testimonials manually and with next/prev
      const ids=['test-1','test-2','test-3'];
      let idx=0;
      const show = (n)=>{
        ids.forEach((id,i)=>document.getElementById(id).style.display=(i===n? 'block':'none'));
      };
      document.getElementById('next').addEventListener('click',()=>{idx=(idx+1)%ids.length;show(idx)});
      document.getElementById('prev').addEventListener('click',()=>{idx=(idx-1+ids.length)%ids.length;show(idx)});
      setInterval(()=>{idx=(idx+1)%ids.length;show(idx)},4800);

      // keyboard for accessibility
      document.querySelectorAll('.cred').forEach(el=>{
        el.addEventListener('focus',()=>{const tip=el.querySelector('.tip');if(tip){tip.style.opacity=1;tip.style.transform='translate(-50%,0)'}});
        el.addEventListener('blur',()=>{const tip=el.querySelector('.tip');if(tip){tip.style.opacity=0;tip.style.transform='translate(-50%,6px)'}});
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#032226;--panel:rgba(255,255,255,0.04);--muted:rgba(255,255,255,0.6);--accent:#8ee0cf}
    body{margin:0;font-family:Inter,system-ui,Arial;color:#eafcf8;background:linear-gradient(180deg,var(--bg),#021015);min-height:100vh;background-image:url('assets/img/pattern.svg')}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;background:rgba(255,255,255,0.01)}
    .logo{width:44px;height:44px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#39b8c7);display:flex;align-items:center;justify-content:center;font-weight:700}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    main{max-width:1000px;margin:24px auto;padding:18px;display:grid;grid-template-columns:1fr 340px;gap:20px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:20px;border-radius:12px}
    h1{margin:0 0 8px 0}
    .mixer{display:flex;flex-direction:column;gap:12px}
    .slider{width:100%;-webkit-appearance:none;height:10px;border-radius:10px;background:linear-gradient(90deg,#233,#468);outline:none}
    .options{display:flex;gap:12px}
    .opt{flex:1;padding:10px;border-radius:10px;text-align:center;background:rgba(255,255,255,0.02);cursor:pointer}
    .opt.active{background:linear-gradient(180deg,var(--accent),#37a7b2);color:#022}
    .program{margin-top:14px;padding:12px;border-radius:10px;background:rgba(255,255,255,0.02)}
    .price{font-weight:700;font-size:20px;color:#eafffb}
    form{display:flex;flex-direction:column;gap:10px}
    input,select,button,textarea{padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eafffb}
    button.primary{background:var(--accent);border:none;color:#022;padding:12px;border-radius:10px;font-weight:700}
    .note{font-size:13px;color:var(--muted)}
    .disclaimer{font-size:13px;color:#c7fff6;background:rgba(255,255,255,0.01);padding:10px;border-radius:8px;margin-top:8px}
    @media(max-width:880px){main{grid-template-columns:1fr;padding:14px} .aside{order:2}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Booking nav">
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="pricing.html">Memberships</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="panel">
      <h1>Reserve a seat</h1>
      <p class="note">Pick the tone level that fits your current needs. The recommendations and session framing below adjust instantly.</p>

      <div class="mixer" aria-label="Sound preference mixer">
        <label for="mix">Sound preference</label>
        <div class="options" role="tablist">
          <div class="opt active" data-level="gentle" role="tab" tabindex="0">Gentle</div>
          <div class="opt" data-level="medium" role="tab" tabindex="0">Medium</div>
          <div class="opt" data-level="intense" role="tab" tabindex="0">Intense</div>
        </div>

        <div class="program" id="program">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div style="font-size:15px;color:var(--muted)">Recommended session</div>
              <div id="p-name" style="font-weight:700;font-size:18px;color:#eafffb">Soft Resonance</div>
            </div>
            <div class="price" id="p-price">Included with membership</div>
          </div>

          <div id="p-desc" style="margin-top:10px;color:var(--muted);font-size:14px">Layered bowls and wind chimes with long decays; steady tempo cues for a calm return.</div>
        </div>
      </div>

      <form id="booking-form" style="margin-top:16px" onsubmit="return false;">
        <input type="text" name="name" placeholder="Full name" required>
        <input type="email" name="email" placeholder="Email" required>
        <input type="tel" name="phone" placeholder="Phone (optional)">
        <label for="date">Select date</label>
        <select name="date" id="date">
          <option>Next available: see Calendar</option>
        </select>
        <label for="notes">Notes for facilitator (health considerations)</label>
        <textarea name="notes" rows="3" placeholder="Tell us about any conditions we should know"></textarea>

        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="primary" id="book-btn">{{PRIMARY_CTA_LABEL}}</button>
          <button class="" id="contact-btn" style="background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);padding:10px;border-radius:8px">Call us</button>
        </div>

        <div class="disclaimer">Not a substitute for medical care. If you have a pacemaker, epilepsy, unstable cardiac conditions, or are in psychiatric crisis, please consult a clinician before booking and inform us.</div>
      </form>
    </section>

    <aside class="panel aside">
      <h3>Quick guide</h3>
      <div style="color:var(--muted);font-size:14px">Membership frames: our membership model is for frequent attendees. If you prefer single-event booking, check the Calendar. Members get priority reservation windows and a modest rate advantage.</div>

      <div style="margin-top:12px">
        <strong style="color:#eafffb">Why choose a membership?</strong>
        <ul style="color:var(--muted)">
          <li>Priority booking windows</li>
          <li>Access to short recorded sessions</li>
          <li>Consistent weekly gatherings</li>
        </ul>
      </div>

      <div style="margin-top:12px">
        <strong style="color:#eafffb">Contact</strong>
        <div style="color:var(--muted);font-size:13px">Email: <a href="mailto:{{EMAIL}}" style="color:#bff7f0">{{EMAIL}}</a></div>
        <div style="color:var(--muted);font-size:13px">Phone: <a href="tel:{{PHONE}}" style="color:#bff7f0">{{PHONE}}</a></div>
      </div>
    </aside>
  </main>

  <footer style="padding:18px;color:var(--muted);text-align:center">© {{BUSINESS_NAME}} — Serving calm practices in {{CITY}}, {{STATE}}</footer>

  <script>
    (function(){
      // Mixer logic: switch program recommendations
      const opts=document.querySelectorAll('.opt');
      const pName=document.getElementById('p-name');
      const pDesc=document.getElementById('p-desc');
      const pPrice=document.getElementById('p-price');
      const programs={
        gentle:{name:'Soft Resonance',desc:'Layered singing bowls, long tones and quiet reed; slow cues to support a gentle re-orientation.',price:'Included with membership'},
        medium:{name:'Balanced Clearing',desc:'Mixed bowls and light gong strokes with measured crescendos; clear markers for both rest and re-entry.',price:'Recommended for new members'},
        intense:{name:'Focused Reset',desc:'Deeper metal tones with rhythmic pulses and strategic pauses; designed for stronger somatic release.',price:'Intensive session — membership required'}
      };

      function setLevel(level){
        Object.values(opts).forEach(o=>o.classList.remove('active'));
